static inline uint64_t
erx_msgtag_raw_words_get(uint64_t value)
{
	return (((uint64_t)value >> 0 & UINT64_C(63)) << 0);
}

static inline bool
erx_msgtag_raw_words_set(uint64_t *value, uint64_t bits)
{
	uint64_t raw;

	if (value == NULL || bits > UINT64_C(63))
		return (false);
	raw = (uint64_t)*value;
	raw = (raw & ~UINT64_C(63)) |
	    ((bits >> 0) << 0);
	*value = raw;
	return (true);
}

